function translateVisibleText() { const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT); let node; const labels = Object.entries(koreanLabels).sort(([a], [b]) => b.length - a.length); while ((node = walker.nextNode())) { let value = node.nodeValue; labels.forEach(([english, korean]) => { if (english.length > 2 && value.includes(english)) value = value.replaceAll(english, korean) }); node.nodeValue = value } document.querySelectorAll('input[placeholder], textarea[placeholder]').forEach((input) => { const value = input.getAttribute('placeholder'); if (koreanLabels[value]) input.setAttribute('placeholder', koreanLabels[value]) }) }
